const numbers=[20000, 37000, 100000, 13000, 67000, 70000]

function min(prices){
    let minPrice=prices[0];
    for(let price of prices)
    {
        if(price<minPrice)
            {
                minPrice=price;
            }
    }
    return minPrice;
}
const value=min(numbers);
console.log(value);